    ops = {'+', '-', '*', '/'}
    for t in tokens:
        if isinstance(t, (int, float)):
            stack.append(int(t))
            continue
        t = str(t).strip()
        if t in ops:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                q = abs(a) // abs(b) if b != 0 else 0
                if (a < 0) != (b < 0) and q != 0:
                    q = -q
                stack.append(q)
        else:
            try:
                stack.append(int(t))
            except ValueError:
                try:
                    stack.append(float(t))
                except:
                    pass
    return stack[-1] if stack else 0

